#pragma once
inline nlohmann::json rendering107Proof(hb::gpu::Device& gpu,const std::string& fixture){
 using namespace hb::gpu;std::ifstream input(fixture);if(!input)throw std::runtime_error("107 fixture missing");const auto packets=nlohmann::json::parse(input).at("rendering107");SceneRenderer r(gpu,64,64);SceneFrame frame;frame.clear={0,0,0,1};frame.eye={0,0,-1,1};frame.screenEffects.emplace();auto& s=*frame.screenEffects;s.eye=frame.eye;s.forward={0,0,1,0};s.path={1,12,1,0};s.camera={.1f,100,1,1};s.geometry={0,20,1,4};
 auto visible=r.createMesh({{{-1,-1,.6f},{0,0,-1}},{{1,-1,.6f},{0,0,-1}},{{1,1,.6f},{0,0,-1}},{{-1,1,.6f},{0,0,-1}}},{0,1,2,0,2,3});SceneMaterial black;black.unlit=true;black.color={0,0,0,1};nlohmann::json proof;int rejected=0;
 for(const std::string kind:{"nested","inside","environment","noise"}){const auto& p=packets.at(kind);const auto data=p.at("data").get<std::vector<float>>();std::vector<std::uint8_t> bytes(data.size()*4);std::memcpy(bytes.data(),data.data(),bytes.size());auto world=r.createDataTexture(p.at("width").get<UINT>(),p.at("height").get<UINT>(),bytes,4,true);std::optional<decltype(world)> environment;if(!p.at("environmentPacket").is_null()){const auto& e=p.at("environmentPacket");const auto radiance=e.at("data").get<std::vector<float>>();std::vector<std::uint8_t> pixels(radiance.size()*4);std::memcpy(pixels.data(),radiance.data(),pixels.size());environment.emplace(r.createDataTexture(e.at("width").get<UINT>(),e.at("height").get<UINT>(),pixels,4,true));}r.setPathEnvironment(environment?&*environment:nullptr);s.rayPrograms=readRayPrograms(p.at("rayPrograms"));s.geometryInfo={p.at("width"),p.at("height"),p.at("nodeCount"),p.at("triangleOffset")};s.geometryLimits={256,.001f,p.at("lightsOffset"),p.at("lightCount")};s.transport={p.at("materialsOffset"),p.at("transportVersion"),1,32};s.pathQuality={1,p.at("emitterOffset"),p.at("emitterCount"),p.at("operationMask")[2]};s.pathLens={0,10,p.at("operationMask")[0],p.at("operationMask")[1]};s.pathMap=p.at("pathMap").get<std::array<float,4>>();s.pathOptions={1,p.at("mediumCount"),0,0};s.pathDenoise={0,3,32,.02f};s.path[3]=0;s.inverseVP=identity;if(kind=="inside")s.inverseVP[14]=.45f;r.setGeometryScene(&world);
  const auto capture=[&](){r.begin(frame);r.draw(visible,identity,identity,black);return r.readPixels();};const auto color=[](const auto& rgba){const auto at=(32*64+32)*4;return std::array<int,3>{rgba[at],rgba[at+1],rgba[at+2]};};const auto first=capture();proof[kind]["first"]=color(first);
  if(kind=="nested"||kind=="inside"){const auto rgb=color(first);assert(rgb[1]>rgb[0]+60&&rgb[1]>rgb[2]+60);}
  if(kind=="environment"){s.pathMap[3]=3.141592654f;const auto rotated=color(capture());proof[kind]["rotated"]=rotated;assert(std::abs(rotated[0]-color(first)[0])+std::abs(rotated[1]-color(first)[1])>100);s.pathOptions[0]=0;const auto zero=color(capture());assert(zero[0]<5&&zero[1]<5&&zero[2]<5);proof[kind]["zero"]=zero;}
  if(kind=="noise"){const auto variance=[](const auto& rgba){double sum=0,sum2=0;for(int y=16;y<48;y++)for(int x=16;x<48;x++){double v=rgba[(y*64+x)*4];sum+=v;sum2+=v*v;}return std::array<double,2>{sum/1024,sum2/1024-(sum/1024)*(sum/1024)};};const auto raw=variance(first);s.path[3]=1;s.pathDenoise[0]=1;const auto filtered=capture();const auto smooth=variance(filtered);assert(smooth[1]<raw[1]*.85);assert(std::abs(smooth[0]-raw[0])<30);assert(std::equal(first.begin(),first.begin()+64*4,filtered.begin()));proof[kind]["raw"]=raw;proof[kind]["filtered"]=smooth;const auto activeBytes=r.bloomTextureBytes();s.pathDenoise[0]=0;const auto disabled=capture();assert(disabled==first);assert(r.bloomTextureBytes()+64*64*24==activeBytes);proof[kind]["lazyBytes"]=64*64*24;proof[kind]["zeroIsRaw"]=true;
   for(int n=0;n<4;n++){const auto saved=s;if(n==0)s.pathDenoise[1]=5;if(n==1)s.pathMap[0]=.25f;if(n==2)s.pathOptions[0]=-1;if(n==3)s.pathMap[1]=20000;try{r.begin(frame);}catch(const std::exception&){rejected++;}s=saved;}assert(rejected==4);
  }r.setPathEnvironment(nullptr);r.setGeometryScene(nullptr);
 }frame.screenEffects.reset();r.begin(frame);assert(r.bloomTextureBytes()==0);proof["passed"]=true;proof["actualHLSLBytecode"]=true;proof["insideNestedMedia"]=true;proof["edgeBackgroundUnchanged"]=true;proof["rawHistoryPreserved"]=true;proof["typedGuards"]=rejected;proof["disabledResourcesZero"]=true;return proof;
}
